    _NAME_COUNT = len(string.ascii_uppercase) ** 2 * 1000

    def __init__(self) -> None:
        self._name: str | None = None
        self._pending_release: str | None = None

    @staticmethod
    def _candidate() -> str:
        letters = random.choices(string.ascii_uppercase, k=2)
        return "".join(letters) + f"{random.randint(0, 999):03d}"

    @classmethod
    def _allocate_name(cls) -> str:
        if len(cls._used) >= cls._NAME_COUNT:
            raise RuntimeError("robot name namespace exhausted")

        for _ in range(10_000):
            candidate = cls._candidate()
            if candidate not in cls._used:
                cls._used.add(candidate)
                return candidate

        raise RuntimeError("unable to allocate a unique robot name")

    @property
    def name(self) -> str:
        if self._name is None:
            new_name = type(self)._allocate_name()
            if self._pending_release is not None:
                type(self)._used.discard(self._pending_release)
                self._pending_release = None
            self._name = new_name
        return self._name

    def reset(self) -> None:
        if self._name is not None:
            self._pending_release = self._name
            self._name = None
        pass

